const HONOR_TROPHY_IMAGE: Record<string, string> = {
  "Premier League": "/assets/lfc/trophies/league-title.svg",
  "Champions League": "/assets/lfc/trophies/european-cup.svg",
  "FA Cup": "/assets/lfc/trophies/fa-cup.svg",
  "Carabao Cup": "/assets/lfc/trophies/league-cup.svg",
  "League Cup": "/assets/lfc/trophies/league-cup.svg",
  "FIFA Club World Cup": "/assets/lfc/trophies/fifa-club-world-cup.svg",
  "UEFA Super Cup": "/assets/lfc/trophies/uefa-super-cup.svg",
  "UEFA Cup": "/assets/lfc/trophies/uefa-cup.svg",
  "FA Community Shield": "/assets/lfc/trophies/community-shield.svg",
  "Community Shield": "/assets/lfc/trophies/community-shield.svg",
};

const POS_ACCENT: Record<PlayerPosition, { bg: string; text: string }> = {
  goalkeeper: { bg: "bg-yellow-400", text: "text-black" },
  defender: { bg: "bg-blue-600", text: "text-white" },
  midfielder: { bg: "bg-green-700", text: "text-white" },
  forward: { bg: "bg-lfc-red", text: "text-white" },
};

// ─── Static generation ───────────────────────────────────────────────────────

/** First ~155 characters of a bio, cut at a word boundary, for meta descriptions. */
function summarize(text: string, max = 155): string {
  const clean = text.replace(/\s+/g, " ").trim();
  if (clean.length <= max) return clean;
  return `${clean.slice(0, clean.lastIndexOf(" ", max - 1))}…`;
}

/** Paragraphs of the biography shown before "Read more". */
const BIO_LEAD = 2;

/**
 * Split a bio into paragraphs. Bios with blank-line breaks keep them; a bio
 * written as one block is grouped three sentences at a time. (Splitting on
 * every sentence turned the Vietnamese bios into one-line paragraphs.)
 */
function toParagraphs(text: string): string[] {
  const blocks = text.split(/\n{2,}/).map((b) => b.trim()).filter(Boolean);
  if (blocks.length !== 1) return blocks;
  const sentences = blocks[0].match(/[^.!?]+[.!?]+(?:\s+|$)|[^.!?]+$/g) ?? [blocks[0]];
  const paragraphs: string[] = [];
  for (let i = 0; i < sentences.length; i += 3) {
    paragraphs.push(sentences.slice(i, i + 3).join("").trim());
  }
  return paragraphs;
}

export const revalidate = 3600; // live stats come from cached API fetches
// Every player is prerendered below; an unknown slug must 404 here. Rendering it
// on demand returned 200 (soft 404) because loading.tsx starts streaming first.
export const dynamicParams = false;

export async function generateStaticParams() {
  const players = getAllPlayers();
  return players.map((p) => ({ id: p.slug }));
}

export async function generateMetadata({ params }: PageProps): Promise<Metadata> {
  const { id, locale } = await params;
  const player = getPlayerBySlug(id);
  if (!player) return { title: "Player" };
  // metaDescription is English-only; the Vietnamese page gets the opening of
  // the Vietnamese bio instead.
  const viSummary = locale === "vi" ? summarize(getPlayerBio(player.slug, "vi")) : "";
  const description =
    viSummary ||
    player.metaDescription ||
    `${player.name} — ${POSITION_DISPLAY[player.position]} at Liverpool FC.`;
  const images = player.photoLg ? [{ url: player.photoLg, width: 400, height: 400 }] : [];
  const alternates = getHreflangAlternates(`/player/${id}`, locale);
  return {
    title: player.name,
    description,
    alternates,
    openGraph: {
      title: player.name,
      url: alternates.canonical,
      locale: locale === "vi" ? "vi_VN" : "en_GB",
      description,
      type: "profile",
      ...(images.length > 0 && { images }),
      siteName: BRAND.name,
    },
    twitter: {
      card: "summary_large_image",
      title: player.name,
      description,
      ...(player.photoLg && { images: [player.photoLg] }),
    },
  };
}

// ─── Page ────────────────────────────────────────────────────────────────────

export default async function PlayerPage({ params }: PageProps) {
  const { id, locale } = await params;
  setRequestLocale(locale);
  const player = getPlayerBySlug(id);
  if (!player) notFound();

  const t = await getTranslations("PlayerDetail");

  const age = calculateAge(player.dateOfBirth);
  // dateOfBirth is a date-only string (UTC midnight): format in UTC so it never
  // shifts a day, and in the visitor's language.
  const dob = new Date(player.dateOfBirth).toLocaleDateString(locale === "vi" ? "vi-VN" : "en-GB", {
    day: "numeric",
    month: "long",
    year: "numeric",
    timeZone: "UTC",
  });
  const accent = POS_ACCENT[player.position];
  // Fixed per render (the page is cached for an hour) so news ages print the same on server and client.
  // eslint-disable-next-line react-hooks/purity
  const renderedAt = Date.now();
  const { flag, key: nationalityKey } = getNationality(player.nationality);
  const nationality = nationalityKey ? t(`nationalities.${nationalityKey}`) : player.nationality;

  // Headlines usually name a player by surname ("Isak", "Mac Allister").
  const nameParts = player.name.split(" ");
  const surname = nameParts.length > 1 && nameParts.at(-1)!.length >= 4 ? nameParts.at(-1)! : player.name;
  const [playerStats, fplStats, mentions, fanRating] = await Promise.all([
    getPlayerStats(player.id),
    getFplPlayerStats(player.name),
    getArticlesMentioning(surname),
    getPlayerFanRating(player.name).catch(() => null),
  ]);

  // Whole rows only: 6 or 3 on the 3-column grid, 4 or 2 on the 2-column one, never an orphan card.
  const newsCounts = {
    base: Math.min(mentions.length, 3),
    sm: mentions.length >= 4 ? 4 : mentions.length >= 2 ? 2 : mentions.length,
    lg: mentions.length >= 6 ? 6 : mentions.length >= 3 ? 3 : mentions.length,
  };

  const bio = getPlayerBio(player.slug, locale);
  const bioParagraphs = toParagraphs(bio).slice(0, 6);
  const bioLead = bioParagraphs.slice(0, BIO_LEAD);
  const bioRest = bioParagraphs.slice(BIO_LEAD);

  const facts: { label: string; value: string; highlight?: boolean }[] = [
    { label: t("info.nationality"), value: `${flag} ${nationality}` },
    { label: t("info.dob"), value: dob },
    { label: t("info.position"), value: t(`positions.${player.position}`) },
    { label: t("info.status"), value: player.forever ? t("status.forever") : player.onLoan ? t("status.onLoan") : t("status.active"), highlight: player.forever },
    ...(player.height ? [{ label: t("info.height"), value: player.height }] : []),
    ...(player.weight ? [{ label: t("info.weight"), value: player.weight }] : []),
    ...(player.shirtName ? [{ label: t("info.shirtName"), value: player.shirtName }] : []),
  ];

  return (
    <div className="min-h-screen">
      <JsonLd data={[
        await buildLocalizedBreadcrumbJsonLd(locale, [
          { nav: "squad", path: "/squad" },
          { name: player.name, path: `/player/${player.slug}` },
        ]),
        buildPersonJsonLd({
          name: player.name,
          birthDate: player.dateOfBirth,
          nationality: player.nationality,
          image: player.photoLg,
          url: getLocalizedUrl(`/player/${player.slug}`, locale),
          position: player.position,
        }),
      ]} />

      {/* ─── Hero: photo full width above the name on phones, split layout from sm ─── */}
      <header className="relative isolate overflow-hidden border-b border-[var(--line)]">
        <div aria-hidden className="absolute inset-0 -z-10 bg-gradient-to-br from-[var(--surface-2)] via-stadium-bg to-stadium-bg" />
        <div className="page-container pb-6 pt-[calc(var(--header-h)+1rem)] sm:pb-10 sm:pt-[calc(var(--header-h)+1.5rem)]">
          <Link
            href="/squad"
            className="group mb-3 inline-flex min-h-11 items-center gap-2 text-sm text-stadium-muted transition-colors hover:text-white"
          >
            <ArrowLeft size={16} aria-hidden className="transition-transform group-hover:-translate-x-1" />
            {t("backSquad")}
          </Link>

          <div className="flex flex-col gap-5 sm:flex-row sm:items-end sm:gap-8 md:items-center">
            {/* Photo box: capped at ~58% of the screen height on phones; object-contain so square or missing body shots never crop badly */}
            <div className="relative isolate h-[min(58vh,26rem)] w-full shrink-0 sm:aspect-[4/5] sm:h-auto sm:w-56 md:order-2 md:ml-auto md:w-72 lg:w-80">
              {/* The shirt number sits behind the player, centred, so nothing clips it */}
              <span
                aria-hidden
                className="pointer-events-none absolute inset-x-0 bottom-[6%] select-none text-center font-bebas text-[min(62vw,15rem)] leading-[0.8] text-white/[0.07] sm:text-[min(30vw,11rem)] md:text-[14rem] lg:text-[16rem]"
              >
                {player.shirtNumber}
              </span>
              <span aria-hidden className={cn("absolute inset-x-[12%] bottom-0 h-1/2 rounded-full opacity-25 blur-3xl", accent.bg)} />
              <PlayerPhoto
                src={player.localBodyShot}
                fallback={player.localPhoto}
                alt={player.name}
                sizes="(min-width:1024px) 320px, (min-width:768px) 288px, (min-width:640px) 224px, 390px"
                priority
              />
            </div>

            <div className="min-w-0 flex-1 md:order-1 md:pb-0 sm:pb-1">
              <div className="mb-3 flex flex-wrap items-center gap-2 font-barlow text-xs font-bold uppercase tracking-[0.12em]">
                <span className={cn("px-2.5 py-1", accent.bg, accent.text)}>{t(`positions.${player.position}`)}</span>
                {player.onLoan && <span className="bg-amber-500 px-2.5 py-1 text-black">{t("status.onLoan")}</span>}
                {player.forever && <span className="bg-lfc-gold px-2.5 py-1 text-black">{t("status.forever")}</span>}
              </div>
              <p className="font-bebas text-5xl leading-none text-brand sm:text-7xl">{player.shirtNumber}</p>
              <h1 className="mt-1 font-bebas text-4xl leading-[0.95] text-white text-balance sm:text-6xl lg:text-7xl">{player.name}</h1>
              <p className="mt-3 text-[15px] text-stadium-muted">
                <span aria-hidden>{flag} </span>
                {nationality} · {t("info.ageYears", { age })}
              </p>
              <div className="mt-4">
                <PlayerFavouriteButton playerId={player.id} playerName={player.name} playerPhoto={player.photo} />
              </div>
            </div>
          </div>
        </div>
      </header>

      <div className="page-container space-y-10 pb-20 pt-8 sm:space-y-14 sm:pt-12">
        {/* ─── Key facts ─── */}
        <section>
          <SectionHeader title={t("sections.playerInfo")} />
          <dl className="grid grid-cols-2 gap-2 sm:grid-cols-4 sm:gap-3">
            {facts.map((f) => (
              <div key={f.label} className="surface min-w-0 px-4 py-3">
                <dt className="font-barlow text-xs font-semibold uppercase tracking-[0.12em] text-stadium-muted">{f.label}</dt>
                <dd className={cn("mt-1 text-[15px] font-medium leading-snug [overflow-wrap:anywhere]", f.highlight ? "text-lfc-gold" : "text-white")}>{f.value}</dd>
              </div>
            ))}
          </dl>
        </section>

        {/* ─── Season statistics (has its own empty state) ─── */}
        <PlayerSeasonStats
          statistics={playerStats?.statistics ?? []}
          fplStats={fplStats}
          position={player.position}
        />

        {/* ─── Fans' rating this season (from the match pages) ─── */}
        {fanRating && (
          <section className="surface flex flex-wrap items-center gap-x-6 gap-y-2 p-5">
            <p className="font-bebas text-6xl leading-none text-lfc-gold tabular-nums">{fanRating.average.toFixed(1)}</p>
            <div className="min-w-0">
              <h2 className="text-base font-semibold text-white">{t("fanRating.title")}</h2>
              <p className="text-sm text-stadium-muted">{t("fanRating.detail", { matches: fanRating.matches, votes: fanRating.votes })}</p>
            </div>
          </section>
        )}

        {/* ─── Latest news naming the player ─── */}
        {mentions.length > 0 && (
          <section>
            <SectionHeader title={t("sections.news", { name: surname })} href="/news" linkLabel={t("sections.allNews")} />
            <div className="sm:grid sm:grid-cols-2 sm:gap-4 lg:grid-cols-3">
              {mentions.map((a, i) => (
                <div
                  key={a.link}
                  className={cn(
                    i < newsCounts.base ? "block" : "hidden",
                    i < newsCounts.sm ? "sm:block" : "sm:hidden",
                    i < newsCounts.lg ? "lg:block" : "lg:hidden",
                  )}
                >
                  <NewsCard article={a} nowMs={renderedAt} />
                </div>
              ))}
            </div>
          </section>
        )}

        {/* ─── Biography ─── */}
        {bio && (
          <section>
            <SectionHeader title={t("sections.biography")} />
            <div className="max-w-[65ch] space-y-4">
              {bioLead.map((paragraph, i) => (
                <p key={i} className="text-base leading-[1.7] text-white/85 sm:text-[17px]">
                  {paragraph.trim()}
                </p>
              ))}
              {bioRest.length > 0 && (
                // Native <details>: the rest of the biography stays in the HTML for search engines.
                <details className="group space-y-4">
                  <summary className="inline-flex min-h-11 cursor-pointer list-none items-center gap-2 font-barlow text-sm font-semibold uppercase tracking-[0.12em] text-brand outline-none hover:text-white focus-visible:ring-2 focus-visible:ring-lfc-red [&::-webkit-details-marker]:hidden">
                    <span className="group-open:hidden">{t("bio.more")}</span>
                    <span className="hidden group-open:inline">{t("bio.less")}</span>
                    <ChevronDown size={16} aria-hidden className="transition-transform group-open:rotate-180" />
                  </summary>
                  {bioRest.map((paragraph, i) => (
                    <p key={i} className="text-base leading-[1.7] text-white/85 sm:text-[17px]">
                      {paragraph.trim()}
                    </p>
                  ))}
                </details>
              )}
            </div>
          </section>
        )}

        {/* ─── Honours ─── */}
        {player.honors.length > 0 && (
          <section>
            <SectionHeader title={t("sections.honours")} eyebrow={t("info.honours")} />
            <ul className="grid grid-cols-1 gap-3 sm:grid-cols-2 lg:grid-cols-3">
              {player.honors.map((honor) => {
                const match = honor.match(/^(.+?)\s*\((.+)\)$/);
                const trophy = match ? match[1] : honor;
                const years = match ? match[2] : "";
                const yearCount = years ? years.split(",").length : 0;
                const trophyImage = HONOR_TROPHY_IMAGE[trophy];

                return (
                  <li key={honor} className="surface relative flex min-h-16 items-center gap-3 p-4">
                    {yearCount > 1 && (
                      <span className="absolute right-3 top-2 font-bebas text-2xl leading-none text-lfc-gold">×{yearCount}</span>
                    )}
                    <span className="relative size-9 shrink-0">
                      {trophyImage ? (
                        <Image src={trophyImage} alt="" fill sizes="36px" className="object-contain" />
                      ) : (
                        <span className="flex size-full items-center justify-center bg-lfc-gold/10">
                          <Trophy size={16} aria-hidden className="text-lfc-gold" />
                        </span>
                      )}
                    </span>
                    <span className="min-w-0 pr-8">
                      <span className="block text-sm font-semibold leading-tight text-white">{trophy}</span>
                      {years && <span className="mt-1 block text-xs text-stadium-muted">{years}</span>}
                    </span>
                  </li>
                );
              })}
            </ul>
          </section>
        )}

        <div className="flex flex-col items-center gap-1 sm:flex-row sm:justify-between">
          <Link
            href="/squad"
            className="group inline-flex min-h-11 items-center gap-2 text-sm font-semibold text-white transition-colors hover:text-brand"
          >
            <ArrowLeft size={16} aria-hidden className="transition-transform group-hover:-translate-x-1" />
            {t("backSquad")}
          </Link>
          <a
            href={`https://www.liverpoolfc.com/team/mens/player/${player.slug}`}
            target="_blank"
            rel="noopener noreferrer"
            className="inline-flex min-h-11 items-center gap-2 text-sm text-stadium-muted transition-colors hover:text-white"
          >
            {t("viewOnLfc")}
            <svg aria-hidden className="size-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
              <path strokeLinecap="round" strokeLinejoin="round" d="M10 6H6a2 2 0 00-2 2v10a2 2 0 002 2h10a2 2 0 002-2v-4M14 4h6m0 0v6m0-6L10 14" />
            </svg>
          </a>
        </div>
      </div>
    </div>
  );
}
